514			subTableNum = DEFAULT_SUB_TABLE_NUM
515		}
516	
517		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
518	
519		var count int64
520		var err error
521		if protocolType > 0 {
522			err = DB.Table(tableName).Where("user_name = ? AND model_name = ? AND protocol_type = ?", userName, modelName, protocolType).Count(&count).Error
523		} else {
524			err = DB.Table(tableName).Where("user_name = ? AND model_name = ?", userName, modelName).Count(&count).Error
525		}
