539	// CountAgentHttpTransactionsBatch 批量查询多个用户-模型组合的记录数（限制并发数）
540	func CountAgentHttpTransactionsBatch(items []RouteRecordCountItem, subTableNum int) map[string]int64 {
541		result := make(map[string]int64)
542		if DB == nil || len(items) == 0 {
543			return result
544		}
545		if subTableNum <= 0 {
546			subTableNum = DEFAULT_SUB_TABLE_NUM
547		}
548	
549		// 去重，避免重复查询
550		seen := make(map[string]bool)
551		var uniqueItems []RouteRecordCountItem
552		for _, item := range items {
553			key := item.UserName + "|" + item.ModelName + "|" + strconv.Itoa(item.ProtocolType)
554			if !seen[key] {
555				seen[key] = true
556				uniqueItems = append(uniqueItems, item)
557			}
558		}
559	
560		// 限制并发数为 10
561		sem := make(chan struct{}, 10)
562		var wg sync.WaitGroup
563		var mu sync.Mutex
564	
565		for _, item := range uniqueItems {
566			wg.Add(1)
567			go func(userName, modelName string, protocolType int) {
568				defer wg.Done()
569				sem <- struct{}{}
570				defer func() { <-sem }()
571				count, err := CountAgentHttpTransactions(userName, modelName, protocolType, subTableNum)
572				if err == nil {
573					mu.Lock()
574					result[userName+"|"+modelName+"|"+strconv.Itoa(protocolType)] = count
575					mu.Unlock()
576				}
577			}(item.UserName, item.ModelName, item.ProtocolType)
578		}
579		wg.Wait()
580		return result
581	}
582	
583	// ProtocolAnalysisStats 协议分析统计
584	type ProtocolAnalysisStats struct {
585		// 通用统计
586		MethodStats     map[string]int64 `json:"method_stats"`
587		URLPatternStats map[string]int64 `json:"url_pattern_stats"`
588		StatusStats     map[string]int64 `json:"status_stats"`
589		AvgElapsedMs    int64            `json:"avg_elapsed_ms"`
590		MinElapsedMs    int64            `json:"min_elapsed_ms"`
591		MaxElapsedMs    int64            `json:"max_elapsed_ms"`
592		AvgReqSize      int64            `json:"avg_req_size"`
593		AvgRespSize     int64            `json:"avg_resp_size"`
594	
595		// 协议特有统计
596		ModelStats      map[string]int64 `json:"model_stats"`
597		StreamCount     int64            `json:"stream_count"`
598		NonStreamCount  int64            `json:"non_stream_count"`
599		HasSystemPrompt int64            `json:"has_system_prompt"`
600		HasToolCall     int64            `json:"has_tool_call"`
601		MultiTurnCount  int64            `json:"multi_turn_count"`
602		SingleTurnCount int64            `json:"single_turn_count"`
603	
604		// 样本说明
605		SampleCount int `json:"sample_count"`
606		SampleLimit int `json:"sample_limit"`
607	}
608	
609	// GetProtocolAnalysisStats 获取协议分析统计（仅分析最近 limit 条记录）
610	// 使用预解析字段，完全避免加载 request_body/response_body 等大字段
611	func GetProtocolAnalysisStats(userName, modelName string, subTableNum int, limit int) (*ProtocolAnalysisStats, error) {
612		if DB == nil {
613			return nil, fmt.Errorf("database not initialized")
614		}
615		if subTableNum <= 0 {
616			subTableNum = DEFAULT_SUB_TABLE_NUM
617		}
618		if limit <= 0 {
619			limit = 500
620		}
621		if limit > 5000 {
622			limit = 5000
623		}
624	
625		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
626	
627		type statsRecord struct {
628			RequestMethod         string
629			RequestURL            string
630			ResponseStatus        string
631			ElapsedMs             int64
632			RequestContentLength  uint64
633			ResponseContentLength uint64
634			IsTask                bool
635			TaskModel             string
636			IsStream              bool
637			HasSystemPrompt       bool
638			HasToolCall           bool
639			MessageCount          int
640			UserMessageCount      int
641		}
642		var records []statsRecord
643	
644		err := DB.Table(tableName).
645			Select("request_method", "request_url", "response_status", "elapsed_ms",
646				"request_content_length", "response_content_length",
647				"is_task", "task_model", "is_stream", "has_system_prompt", "has_tool_call", "message_count", "user_message_count").
648			Where("user_name = ? AND model_name = ?", userName, modelName).
649			Order("id DESC").
650			Limit(limit).
651			Find(&records).Error
652		if err != nil {
653			return nil, fmt.Errorf("failed to query protocol analysis stats: %w", err)
654		}
655	
656		stats := &ProtocolAnalysisStats{
657			MethodStats:     make(map[string]int64),
658			URLPatternStats: make(map[string]int64),
659			StatusStats:     make(map[string]int64),
660			ModelStats:      make(map[string]int64),
661			SampleCount:     len(records),
662			SampleLimit:     limit,
663			MinElapsedMs:    -1,
664			MaxElapsedMs:    -1,
665		}
666	
667		var totalReqSize, totalRespSize, totalElapsed int64
668	
669		for _, rec := range records {
670			// HTTP 方法
671			stats.MethodStats[rec.RequestMethod]++
672	
673			// URL 模式（只保留路径部分）
674			urlPath := rec.RequestURL
675			if idx := strings.LastIndex(urlPath, "?"); idx > 0 {
676				urlPath = urlPath[:idx]
677			}
678			stats.URLPatternStats[urlPath]++
679	
680			// 响应状态
681			stats.StatusStats[rec.ResponseStatus]++
682	
683			// 响应时间
684			totalElapsed += rec.ElapsedMs
685			if stats.MinElapsedMs < 0 || rec.ElapsedMs < stats.MinElapsedMs {
686				stats.MinElapsedMs = rec.ElapsedMs
687			}
688			if stats.MaxElapsedMs < 0 || rec.ElapsedMs > stats.MaxElapsedMs {
689				stats.MaxElapsedMs = rec.ElapsedMs
690			}
691	
692			// 请求/响应大小
693			totalReqSize += int64(rec.RequestContentLength)
694			totalRespSize += int64(rec.ResponseContentLength)
695	
696			// 协议特征统计（使用预解析字段）
697			if rec.TaskModel != "" {
698				stats.ModelStats[rec.TaskModel]++
699			}
700			if rec.IsStream {
701				stats.StreamCount++
702			} else {
703				stats.NonStreamCount++
704			}
705			if rec.HasSystemPrompt {
706				stats.HasSystemPrompt++
707			}
708			if rec.HasToolCall {
709				stats.HasToolCall++
710			}
711			if rec.UserMessageCount > 1 {
712				stats.MultiTurnCount++
713			} else {
714				stats.SingleTurnCount++
715			}
716		}
717	
718		count := int64(len(records))
719		if count > 0 {
720			stats.AvgElapsedMs = totalElapsed / count
721			stats.AvgReqSize = totalReqSize / count
722			stats.AvgRespSize = totalRespSize / count
723		} else {
724			stats.MinElapsedMs = 0
725			stats.MaxElapsedMs = 0
726		}
727	
728		return stats, nil
729	}
730	
731	// isValidTableName 校验表名是否只包含合法字符（字母、数字、下划线）
732	func isValidTableName(tableName string) bool {
733		if tableName == "" {
734			return false
735		}
736		for i := 0; i < len(tableName); i++ {
737			c := tableName[i]
738			if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') && c != '_' {
739				return false
740			}
741		}
742		return true
743	}
744	
745	// IsTableExists 检查表是否存在（使用 GORM Migrator，兼容多种数据库）
746	func IsTableExists(tableName string) bool {
747		if !isValidTableName(tableName) {
748			log.Printf("[WARNING] Invalid table name: %s", tableName)
749			return false
750		}
751		if DB == nil {
752			return false
753		}
754		exists := DB.Migrator().HasTable(tableName)
755		return exists
756	}
757	
758	// ModelUsageStats 模型使用统计
759	type ModelUsageStats struct {
760		CallCount        int64  `json:"call_count"`
761		TokensAllSize    uint64 `json:"tokens_all_size"`
762		TokensInputSize  uint64 `json:"tokens_input_size"`
763		TokensOutputSize uint64 `json:"tokens_output_size"`
764	}
765	
766	// GetModelUsageStatsAll 全平台维度：统计所有分表中指定模型的调用次数和Tokens（按 model_name 匹配 dst_model_name）
767	func GetModelUsageStatsAll(modelName string, subTableNum int) (*ModelUsageStats, error) {
768		if DB == nil {
769			return nil, fmt.Errorf("database not initialized")
770		}
771		if subTableNum <= 0 {
772			subTableNum = DEFAULT_SUB_TABLE_NUM
773		}
774	
775		stats := &ModelUsageStats{}
776		for i := 0; i < subTableNum; i++ {
777			tableName := fmt.Sprintf("TAgentHttpTransactionDataItem_%02d", i)
778			if !IsTableExists(tableName) {
779				continue
780			}
781	
782			var result struct {
783				Count            int64  `gorm:"column:count"`
784				TokensAllSize    uint64 `gorm:"column:tokens_all_size"`
785				TokensInputSize  uint64 `gorm:"column:tokens_input_size"`
786				TokensOutputSize uint64 `gorm:"column:tokens_output_size"`
787			}
788	
789			err := DB.Table(tableName).
790				Select("COUNT(*) as count, COALESCE(SUM(tokens_all_size), 0) as tokens_all_size, COALESCE(SUM(tokens_input_size), 0) as tokens_input_size, COALESCE(SUM(tokens_output_size), 0) as tokens_output_size").
791				Where("dst_model_name = ?", modelName).
792				Scan(&result).Error
793			if err != nil {
794				continue // 忽略单表错误，继续统计其他表
795			}
796	
797			stats.CallCount += result.Count
798			stats.TokensAllSize += result.TokensAllSize
799			stats.TokensInputSize += result.TokensInputSize
800			stats.TokensOutputSize += result.TokensOutputSize
801		}
802	
803		return stats, nil
804	}
805	
806	// GetModelUsageStatsByUser 用户维度：统计指定用户的所有模型调用次数和Tokens（按 user_name + model_name 匹配）
807	func GetModelUsageStatsByUser(userName string, modelName string, subTableNum int) (*ModelUsageStats, error) {
808		if DB == nil {
809			return nil, fmt.Errorf("database not initialized")
810		}
811		if subTableNum <= 0 {
812			subTableNum = DEFAULT_SUB_TABLE_NUM
813		}
814	
815		// 用户维度的数据在特定分表中
816		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
