823			TokensAllSize    uint64 `gorm:"column:tokens_all_size"`
824			TokensInputSize  uint64 `gorm:"column:tokens_input_size"`
825			TokensOutputSize uint64 `gorm:"column:tokens_output_size"`
826		}
827	
828		err := DB.Table(tableName).
829			Select("COUNT(*) as count, COALESCE(SUM(tokens_all_size), 0) as tokens_all_size, COALESCE(SUM(tokens_input_size), 0) as tokens_input_size, COALESCE(SUM(tokens_output_size), 0) as tokens_output_size").
830			Where("user_name = ? AND model_name = ?", userName, modelName).
831			Scan(&result).Error
832		if err != nil {
833			return nil, fmt.Errorf("failed to get model usage stats: %w", err)
834		}
835	
836		return &ModelUsageStats{
837			CallCount:        result.Count,
838			TokensAllSize:    result.TokensAllSize,
839			TokensInputSize:  result.TokensInputSize,
840			TokensOutputSize: result.TokensOutputSize,
841		}, nil
842	}
