1	package main
2	
3	import (
4		"encoding/base64"
5		"fmt"
6		"hash/fnv"
7		"log"
8		"strconv"
9		"strings"
10		"sync"
11		"time"
12		"unicode/utf8"
13	
14		"gorm.io/gorm"
15	)
16	
17	var (
18		agentHttpSubTableMutex sync.Mutex
19	)
20	
21	// GetSubTableIndex 根据用户名和模型名称计算哈希分表索引
22	func GetSubTableIndex(userName, modelName string, subTableNum int) int {
23		h := fnv.New32a()
24		_, _ = h.Write([]byte(userName + "_" + modelName))
25		return int(h.Sum32() % uint32(subTableNum))
26	}
27	
28	// GetAgentHttpTableName 根据用户名和模型名称生成对应的哈希分表名
29	func GetAgentHttpTableName(userName, modelName string, subTableNum int) string {
30		index := GetSubTableIndex(userName, modelName, subTableNum)
31		return fmt.Sprintf("TAgentHttpTransactionDataItem_%02d", index)
32	}
33	
34	// InitAgentHttpSubTables 根据配置的分表数量，自动创建所有分表
35	func InitAgentHttpSubTables(subTableNum int) error {
36		if DB == nil {
37			return fmt.Errorf("database not initialized")
38		}
39		if subTableNum <= 0 {
40			subTableNum = DEFAULT_SUB_TABLE_NUM
41		}
42	
43		logger.Printf("[DB] Initializing %d agent HTTP sub tables...", subTableNum)
44		for i := 0; i < subTableNum; i++ {
45			tableName := fmt.Sprintf("TAgentHttpTransactionDataItem_%02d", i)
46			err := DB.Table(tableName).AutoMigrate(&TAgentHttpTransactionDataItem{})
47			if err != nil {
48				return fmt.Errorf("failed to migrate table %s: %w", tableName, err)
49			}
50			// 手动创建复合索引（避免 GORM AutoMigrate 在 SQLite 上重复创建索引报错）
51			createIndexSQL := fmt.Sprintf("CREATE INDEX IF NOT EXISTS idx_user_model ON %s (user_name, model_name)", tableName)
52			if err := DB.Exec(createIndexSQL).Error; err != nil {
53				return fmt.Errorf("failed to create composite index on %s: %w", tableName, err)
54			}
55			// 创建时间范围查询复合索引（优化 GetTimeRangeStats、GetSessionAnalysis、GetTaskAnalysis 等）
56			createTimeIndexSQL := fmt.Sprintf("CREATE INDEX IF NOT EXISTS idx_user_model_created ON %s (user_name, model_name, created_at)", tableName)
57			if err := DB.Exec(createTimeIndexSQL).Error; err != nil {
58				return fmt.Errorf("failed to create time composite index on %s: %w", tableName, err)
59			}
60			logger.Printf("[DB] Table %s ready", tableName)
61		}
62		logger.Printf("[DB] All %d agent HTTP sub tables initialized", subTableNum)
63	
64		// 一次性回填旧记录的预解析字段（异步执行，不阻塞主线程启动服务）
65		go func() {
66			if err := backfillTransactionTaskFeatures(subTableNum); err != nil {
67				logger.Printf("[WARNING] Failed to backfill task features: %v", err)
68			}
69		}()
70	
71		return nil
72	}
73	
74	// backfillTransactionTaskFeatures 回填所有分表中未解析记录的 Task 特征字段
75	func backfillTransactionTaskFeatures(subTableNum int) error {
76		if DB == nil {
77			return fmt.Errorf("database not initialized")
78		}
79		if subTableNum <= 0 {
80			subTableNum = DEFAULT_SUB_TABLE_NUM
81		}
82	
83		logger.Printf("[DB] Backfilling task features for %d sub tables...", subTableNum)
84		batchSize := 50
85		totalUpdated := 0
86	
87		for i := 0; i < subTableNum; i++ {
88			tableName := fmt.Sprintf("TAgentHttpTransactionDataItem_%02d", i)
89	
90			for {
91				var records []TAgentHttpTransactionDataItem
92				err := DB.Table(tableName).
93					Select("id", "request_method", "request_url", "request_body").
94					Where("is_parsed IS NULL OR is_parsed = ? OR user_message_count IS NULL", false).
95					Limit(batchSize).
96					Find(&records).Error
97				if err != nil {
98					logger.Printf("[WARNING] Backfill query failed for %s: %v", tableName, err)
99					break
100				}
101				if len(records) == 0 {
102					break
103				}
104	
105				for _, rec := range records {
106					isTask, model, isStream, hasSystem, hasTools, msgCount, userMsgCount :=
107						parseRequestBodyFeatures(rec.RequestBody, rec.RequestMethod, rec.RequestURL)
108					err := DB.Table(tableName).Where("id = ?", rec.ID).Updates(map[string]interface{}{
109						"is_parsed":          true,
110						"is_task":            isTask,
111						"task_model":         model,
112						"is_stream":          isStream,
113						"has_system_prompt":  hasSystem,
114						"has_tool_call":      hasTools,
115						"message_count":      msgCount,
116						"user_message_count": userMsgCount,
117					}).Error
118					if err != nil {
119						logger.Printf("[WARNING] Backfill update failed for %s id=%d: %v", tableName, rec.ID, err)
120					} else {
121						totalUpdated++
122					}
123				}
124			}
125		}
126	
127		logger.Printf("[DB] Backfill complete: %d records updated", totalUpdated)
128		return nil
129	}
130	
131	// SaveAgentHttpTransaction 保存一次 HTTP 代理请求响应记录到哈希分表
132	func SaveAgentHttpTransaction(
133		userName, modelName string,
134		userID int64,
135		apiKey string,
136		dstEndPointID uint64,
137		dstModelName string,
138		protocolType int,
139		method, requestURL, remoteAddr string,
140		contentLength int64,
141		headers, body string,
142		status string,
143		respContentLength int64,
144		respHeaders, respBody string,
145		requestStartAt, requestEndAt, responseStartAt, responseEndAt time.Time,
146		elapsedMs int64,
147		toolIdentifier string,
148		subTableNum int,
149		tokensInputSize, tokensOutputSize, tokensAllSize uint64,
150	) error {
151		agentHttpSubTableMutex.Lock()
152		defer agentHttpSubTableMutex.Unlock()
153	
154		if DB == nil {
155			return fmt.Errorf("database not initialized")
156		}
157		if subTableNum <= 0 {
158			subTableNum = DEFAULT_SUB_TABLE_NUM
159		}
160	
161		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
162	
163		// 确保目标表存在（若分表数量变更或首次写入）
164		if !IsTableExists(tableName) {
165			err := DB.Table(tableName).AutoMigrate(&TAgentHttpTransactionDataItem{})
166			if err != nil {
167				return fmt.Errorf("failed to auto-migrate table %s: %w", tableName, err)
168			}
169		}
170	
171		// 容错处理：response_body 可能包含非 UTF-8 字节（MiniMax 等模型会输出包含
172		// 不可打印字符的 thinking 块 / 二进制签名等）。MySQL utf8 列直接 INSERT 会
173		// 报 Error 1366，导致整条记录丢弃，/ChatAnalysis 上看不到任何记录。
174		//
175		// 容错处理：response_body 可能包含非 UTF-8 字节（MiniMax 等模型会输出包含
176		// 不可打印字符的 thinking 块 / 二进制签名等）。MySQL utf8 列直接 INSERT 会
177		// 报 Error 1366，导致整条记录丢弃，/ChatAnalysis 上看不到任何记录。
178		//
179		// 处理策略：
180		//   1) response_body: 与 request_body 一致做 base64 编码后再存。前端页面
181		//      的 decodeBody() 已经在调用 atob + TextDecoder('utf-8')，天然兼容。
182		//   2) headers / 其他文本字段: 用 UTF-8 替换（U+FFFD）兜底，绝不让 INSERT 失败。
183		respBodyForLog := base64.StdEncoding.EncodeToString([]byte(respBody))
184	
185		record := &TAgentHttpTransactionDataItem{
186			UserID:                uint64(userID),
187			UserName:              userName,
188			ModelName:             modelName,
189			DstModelName:          dstModelName,
190			APIKey:                apiKey,
191			DstEndPointID:         dstEndPointID,
192			ProtocolType:          protocolType,
193			RequestMethod:         method,
194			RequestURL:            requestURL,
195			RequestRemoteAddr:     sanitizeUTF8(remoteAddr),
196			RequestContentLength:  uint64(contentLength),
197			RequestHeaders:        sanitizeUTF8(headers),
198			RequestBody:           body,
199			ResponseStatus:        status,
200			ResponseContentLength: uint64(respContentLength),
201			ResponseHeaders:       sanitizeUTF8(respHeaders),
202			ResponseBody:          respBodyForLog,
203			TokensInputSize:       tokensInputSize,
204			TokensOutputSize:      tokensOutputSize,
205			TokensAllSize:         tokensAllSize,
206			RequestStartAt:        requestStartAt,
207			RequestEndAt:          requestEndAt,
208			ResponseStartAt:       responseStartAt,
209			ResponseEndAt:         responseEndAt,
210			ElapsedMs:             elapsedMs,
211			ToolIdentifier:        sanitizeUTF8(toolIdentifier),
212		}
213	
214		// 预解析 request_body 特征，避免后续查询时重复解析大字段
215		record.IsParsed = true
216		record.IsTask, record.TaskModel, record.IsStream, record.HasSystemPrompt, record.HasToolCall, record.MessageCount, record.UserMessageCount =
217			parseRequestBodyFeatures(body, method, requestURL)
218	
219		err := DB.Table(tableName).Create(record).Error
220		if err != nil {
221			return fmt.Errorf("failed to save record to %s: %w", tableName, err)
222		}
223		return nil
224	}
