440	// GetTimeRangeStats 查询指定用户按小时的调用统计
441	func GetTimeRangeStats(userName, modelName string, subTableNum int, days int) ([]TimeRangeStat, error) {
442		if DB == nil {
443			return nil, fmt.Errorf("database not initialized")
444		}
445		if subTableNum <= 0 {
446			subTableNum = DEFAULT_SUB_TABLE_NUM
447		}
448		if days <= 0 {
449			days = 30
450		}
451		if days > 365 {
452			days = 365
453		}
454	
455		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
456	
457		// 按小时查询
458		var results []struct {
459			Hour  string `gorm:"column:hour"`
460			Count int64  `gorm:"column:count"`
461		}
462	
463		// 校验表名格式，防止 SQL 注入
464		if !isValidTableName(tableName) {
465			return nil, fmt.Errorf("invalid table name: %s", tableName)
466		}
467	
468		query := fmt.Sprintf(`
469			SELECT DATE_FORMAT(created_at, '%%Y-%%m-%%d %%H:00') as hour, COUNT(*) as count
470			FROM %s
471			WHERE user_name = ?
472			  AND model_name = ?
473			  AND created_at >= DATE_SUB(NOW(), INTERVAL ? DAY)
474			GROUP BY DATE_FORMAT(created_at, '%%Y-%%m-%%d %%H:00')
475			ORDER BY hour ASC
476		`, tableName)
477	
478		err := DB.Raw(query, userName, modelName, days).Scan(&results).Error
479		if err != nil {
480			return nil, fmt.Errorf("failed to get time range stats: %w", err)
481		}
482	
483		// 创建查询结果 map
484		resultMap := make(map[string]int64)
485		for _, r := range results {
486			resultMap[r.Hour] = r.Count
487		}
488	
489		// 生成完整的小时槽位列表（包含无数据的小时，count=0）
490		now := time.Now()
491		startTime := now.Add(-time.Duration(days) * 24 * time.Hour)
492		// 对齐到整点
493		startTime = startTime.Truncate(time.Hour)
494	
495		var stats []TimeRangeStat
496		for t := startTime; !t.After(now); t = t.Add(time.Hour) {
497			hourKey := t.Format("2006-01-02 15:04")
498			count := resultMap[hourKey]
499			stats = append(stats, TimeRangeStat{
500				Date:  hourKey,
501				Count: count,
502			})
503		}
504	
505		return stats, nil
506	}
