609	// GetProtocolAnalysisStats 获取协议分析统计（仅分析最近 limit 条记录）
610	// 使用预解析字段，完全避免加载 request_body/response_body 等大字段
611	func GetProtocolAnalysisStats(userName, modelName string, subTableNum int, limit int) (*ProtocolAnalysisStats, error) {
612		if DB == nil {
613			return nil, fmt.Errorf("database not initialized")
614		}
615		if subTableNum <= 0 {
616			subTableNum = DEFAULT_SUB_TABLE_NUM
617		}
618		if limit <= 0 {
619			limit = 500
620		}
621		if limit > 5000 {
622			limit = 5000
623		}
624	
625		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
626	
627		type statsRecord struct {
628			RequestMethod         string
629			RequestURL            string
630			ResponseStatus        string
631			ElapsedMs             int64
632			RequestContentLength  uint64
633			ResponseContentLength uint64
634			IsTask                bool
635			TaskModel             string
636			IsStream              bool
637			HasSystemPrompt       bool
638			HasToolCall           bool
639			MessageCount          int
640			UserMessageCount      int
641		}
642		var records []statsRecord
643	
644		err := DB.Table(tableName).
645			Select("request_method", "request_url", "response_status", "elapsed_ms",
646				"request_content_length", "response_content_length",
647				"is_task", "task_model", "is_stream", "has_system_prompt", "has_tool_call", "message_count", "user_message_count").
648			Where("user_name = ? AND model_name = ?", userName, modelName).
649			Order("id DESC").
650			Limit(limit).
651			Find(&records).Error
652		if err != nil {
653			return nil, fmt.Errorf("failed to query protocol analysis stats: %w", err)
654		}
655	
656		stats := &ProtocolAnalysisStats{
657			MethodStats:     make(map[string]int64),
658			URLPatternStats: make(map[string]int64),
659			StatusStats:     make(map[string]int64),
660			ModelStats:      make(map[string]int64),
661			SampleCount:     len(records),
662			SampleLimit:     limit,
663			MinElapsedMs:    -1,
664			MaxElapsedMs:    -1,
665		}
666	
667		var totalReqSize, totalRespSize, totalElapsed int64
668	
669		for _, rec := range records {
670			// HTTP 方法
671			stats.MethodStats[rec.RequestMethod]++
672	
673			// URL 模式（只保留路径部分）
674			urlPath := rec.RequestURL
675			if idx := strings.LastIndex(urlPath, "?"); idx > 0 {
676				urlPath = urlPath[:idx]
677			}
678			stats.URLPatternStats[urlPath]++
679	
680			// 响应状态
681			stats.StatusStats[rec.ResponseStatus]++
682	
683			// 响应时间
684			totalElapsed += rec.ElapsedMs
685			if stats.MinElapsedMs < 0 || rec.ElapsedMs < stats.MinElapsedMs {
686				stats.MinElapsedMs = rec.ElapsedMs
687			}
688			if stats.MaxElapsedMs < 0 || rec.ElapsedMs > stats.MaxElapsedMs {
689				stats.MaxElapsedMs = rec.ElapsedMs
690			}
691	
692			// 请求/响应大小
693			totalReqSize += int64(rec.RequestContentLength)
694			totalRespSize += int64(rec.ResponseContentLength)
695	
696			// 协议特征统计（使用预解析字段）
697			if rec.TaskModel != "" {
698				stats.ModelStats[rec.TaskModel]++
699			}
700			if rec.IsStream {
701				stats.StreamCount++
702			} else {
703				stats.NonStreamCount++
704			}
705			if rec.HasSystemPrompt {
706				stats.HasSystemPrompt++
707			}
708			if rec.HasToolCall {
709				stats.HasToolCall++
710			}
711			if rec.UserMessageCount > 1 {
712				stats.MultiTurnCount++
713			} else {
714				stats.SingleTurnCount++
715			}
716		}
717	
718		count := int64(len(records))
719		if count > 0 {
720			stats.AvgElapsedMs = totalElapsed / count
721			stats.AvgReqSize = totalReqSize / count
722			stats.AvgRespSize = totalRespSize / count
723		} else {
724			stats.MinElapsedMs = 0
725			stats.MaxElapsedMs = 0
726		}
727	
728		return stats, nil
729	}
730	
731	// isValidTableName 校验表名是否只包含合法字符（字母、数字、下划线）
732	func isValidTableName(tableName string) bool {
733		if tableName == "" {
734			return false
735		}
736		for i := 0; i < len(tableName); i++ {
737			c := tableName[i]
738			if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') && c != '_' {
739				return false
740			}
741		}
742		return true
743	}
744	
745	// IsTableExists 检查表是否存在（使用 GORM Migrator，兼容多种数据库）
746	func IsTableExists(tableName string) bool {
747		if !isValidTableName(tableName) {
748			log.Printf("[WARNING] Invalid table name: %s", tableName)
749			return false
750		}
751		if DB == nil {
752			return false
753		}
754		exists := DB.Migrator().HasTable(tableName)
755		return exists
756	}
