539	// CountAgentHttpTransactionsBatch 批量查询多个用户-模型组合的记录数（限制并发数）
540	func CountAgentHttpTransactionsBatch(items []RouteRecordCountItem, subTableNum int) map[string]int64 {
541		result := make(map[string]int64)
542		if DB == nil || len(items) == 0 {
543			return result
544		}
545		if subTableNum <= 0 {
546			subTableNum = DEFAULT_SUB_TABLE_NUM
547		}
548	
549		// 去重，避免重复查询
550		seen := make(map[string]bool)
551		var uniqueItems []RouteRecordCountItem
552		for _, item := range items {
553			key := item.UserName + "|" + item.ModelName + "|" + strconv.Itoa(item.ProtocolType)
554			if !seen[key] {
555				seen[key] = true
556				uniqueItems = append(uniqueItems, item)
557			}
558		}
559	
560		// 限制并发数为 10
561		sem := make(chan struct{}, 10)
562		var wg sync.WaitGroup
563		var mu sync.Mutex
564	
565		for _, item := range uniqueItems {
566			wg.Add(1)
567			go func(userName, modelName string, protocolType int) {
568				defer wg.Done()
569				sem <- struct{}{}
570				defer func() { <-sem }()
571				count, err := CountAgentHttpTransactions(userName, modelName, protocolType, subTableNum)
572				if err == nil {
573					mu.Lock()
574					result[userName+"|"+modelName+"|"+strconv.Itoa(protocolType)] = count
575					mu.Unlock()
576				}
577			}(item.UserName, item.ModelName, item.ProtocolType)
578		}
579		wg.Wait()
580		return result
581	}
