731	// isValidTableName 校验表名是否只包含合法字符（字母、数字、下划线）
732	func isValidTableName(tableName string) bool {
733		if tableName == "" {
734			return false
735		}
736		for i := 0; i < len(tableName); i++ {
737			c := tableName[i]
738			if !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9') && c != '_' {
739				return false
740			}
741		}
742		return true
743	}
