384	// IDRangeStat ID范围段统计
385	type IDRangeStat struct {
386		RangeStart uint64 `json:"range_start"`
387		RangeEnd   uint64 `json:"range_end"`
388		Count      int64  `json:"count"`
389	}
390	
391	// TimeRangeStat 时间范围统计
392	type TimeRangeStat struct {
393		Date  string `json:"date"`
394		Count int64  `json:"count"`
395	}
