397	// GetIDRangeStats 查询指定用户在ID范围段内的统计
398	func GetIDRangeStats(userName, modelName string, subTableNum int, rangeSize int) ([]IDRangeStat, error) {
399		if DB == nil {
400			return nil, fmt.Errorf("database not initialized")
401		}
402		if subTableNum <= 0 {
403			subTableNum = DEFAULT_SUB_TABLE_NUM
404		}
405		if rangeSize <= 0 {
406			rangeSize = 1000
407		}
408	
409		tableName := GetAgentHttpTableName(userName, modelName, subTableNum)
410	
411		var maxID uint64
412		err := DB.Table(tableName).Select("COALESCE(MAX(id), 0)").Where("user_name = ? AND model_name = ?", userName, modelName).Scan(&maxID).Error
413		if err != nil {
414			return nil, fmt.Errorf("failed to get max id: %w", err)
415		}
416		if maxID == 0 {
417			return nil, nil
418		}
419	
420		var stats []IDRangeStat
421		for start := uint64(1); start <= maxID; start += uint64(rangeSize) {
422			end := start + uint64(rangeSize) - 1
423			if end > maxID {
424				end = maxID
425			}
426			var count int64
427			err := DB.Table(tableName).Where("user_name = ? AND model_name = ? AND id >= ? AND id <= ?", userName, modelName, start, end).Count(&count).Error
428			if err != nil {
429				return nil, fmt.Errorf("failed to count id range %d-%d: %w", start, end, err)
430			}
431			stats = append(stats, IDRangeStat{
432				RangeStart: start,
433				RangeEnd:   end,
434				Count:      count,
435			})
436		}
437		return stats, nil
438	}
