// IDRangeStat ID范围段统计
type IDRangeStat struct {
	RangeStart uint64 `json:"range_start"`
	RangeEnd   uint64 `json:"range_end"`
	Count      int64  `json:"count"`
}

// TimeRangeStat 时间范围统计
type TimeRangeStat struct {
	Date  string `json:"date"`
	Count int64  `json:"count"`
}

// GetIDRangeStats 查询指定用户在ID范围段内的统计
func GetIDRangeStats(userName, modelName string, subTableNum int, rangeSize int) ([]IDRangeStat, error) {
	if DB == nil {
		return nil, fmt.Errorf("database not initialized")
	}
	if subTableNum <= 0 {
		subTableNum = DEFAULT_SUB_TABLE_NUM
	}
	if rangeSize <= 0 {
		rangeSize = 1000
	}

	tableName := GetAgentHttpTableName(userName, modelName, subTableNum)

	var maxID uint64
	err := DB.Table(tableName).Select("COALESCE(MAX(id), 0)").Where("user_name = ? AND model_name = ?", userName, modelName).Scan(&maxID).Error
	if err != nil {
		return nil, fmt.Errorf("failed to get max id: %w", err)
	}
	if maxID == 0 {
		return nil, nil
	}

	var stats []IDRangeStat
	for start := uint64(1); start <= maxID; start += uint64(rangeSize) {
		end := start + uint64(rangeSize) - 1
		if end > maxID {
			end = maxID
		}
		var count int64
		err := DB.Table(tableName).Where("user_name = ? AND model_name = ? AND id >= ? AND id <= ?", userName, modelName, start, end).Count(&count).Error
		if err != nil {
			return nil, fmt.Errorf("failed to count id range %d-%d: %w", start, end, err)
		}
		stats = append(stats, IDRangeStat{
			RangeStart: start,
			RangeEnd:   end,
			Count:      count,
		})
	}
	return stats, nil
}

// GetTimeRangeStats 查询指定用户按小时的调用统计
func GetTimeRangeStats(userName, modelName string, subTableNum int, days int) ([]TimeRangeStat, error) {
	if DB == nil {
		return nil, fmt.Errorf("database not initialized")
	}
	if subTableNum <= 0 {
		subTableNum = DEFAULT_SUB_TABLE_NUM
	}
	if days <= 0 {
		days = 30
	}
	if days > 365 {
		days = 365
	}

	tableName := GetAgentHttpTableName(userName, modelName, subTableNum)

	// 按小时查询
	var results []struct {
		Hour  string `gorm:"column:hour"`
		Count int64  `gorm:"column:count"`
	}

	// 校验表名格式，防止 SQL 注入
	if !isValidTableName(tableName) {
		return nil, fmt.Errorf("invalid table name: %s", tableName)
	}

	query := fmt.Sprintf(`
		SELECT DATE_FORMAT(created_at, '%%Y-%%m-%%d %%H:00') as hour, COUNT(*) as count
		FROM %s
		WHERE user_name = ?
		  AND model_name = ?
		  AND created_at >= DATE_SUB(NOW(), INTERVAL ? DAY)
		GROUP BY DATE_FORMAT(created_at, '%%Y-%%m-%%d %%H:00')
		ORDER BY hour ASC
	`, tableName)

	err := DB.Raw(query, userName, modelName, days).Scan(&results).Error
	if err != nil {
		return nil, fmt.Errorf("failed to get time range stats: %w", err)
	}

	// 创建查询结果 map
	resultMap := make(map[string]int64)
	for _, r := range results {
		resultMap[r.Hour] = r.Count
	}

	// 生成完整的小时槽位列表（包含无数据的小时，count=0）
	now := time.Now()
	startTime := now.Add(-time.Duration(days) * 24 * time.Hour)
	// 对齐到整点
	startTime = startTime.Truncate(time.Hour)

	var stats []TimeRangeStat
	for t := startTime; !t.After(now); t = t.Add(time.Hour) {
		hourKey := t.Format("2006-01-02 15:04")
		count := resultMap[hourKey]
		stats = append(stats, TimeRangeStat{
			Date:  hourKey,
			Count: count,
		})
	}

	return stats, nil
}

