  try {
    var resp = await fetch(apiUrl('UserLoginInterface'), {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(body)
    });
    var data = await resp.json();
    if (data.success) {
      window.location.href = './';
