152	function toggleApiKeyVisibility() {
153	  var input = document.getElementById('apiKey');
154	  input.type = input.type === 'password' ? 'text' : 'password';
155	}
156	
157	// 表单提交处理（传统 form 提交，支持 Chrome 密码管理器）
158	function doModelLoginFormSubmit(e) {
159	  // 同步验证码 ID 到隐藏字段
160	  document.getElementById('formCaptchaId').value = captchaId;
161	  return true; // 允许表单正常提交
162	}
163	
164	// 页面加载时获取验证码
165	document.addEventListener('DOMContentLoaded', refreshCaptcha);
166	</script>
167	</body>
168	</html>`
