10		fmt.Fprint(w, userLoginPageHTML)
11	}
12	
13	const userLoginPageHTML = `<!DOCTYPE html>
14	<html lang="zh-CN">
15	<head>
16	<meta charset="UTF-8">
17	<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
18	<title>用户登录 - Lsm AI Tokens 代理服务</title>
19	<style>
20	*{margin:0;padding:0;box-sizing:border-box}
21	body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f5f5f7;color:#333;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px}
22	.login-box{background:#fff;border-radius:12px;padding:30px;width:100%;max-width:400px;box-shadow:0 2px 10px rgba(0,0,0,.1)}
23	h1{font-size:20px;text-align:center;margin-bottom:20px;color:#1a1a1a}
24	.tabs{display:flex;margin-bottom:20px;border-bottom:1px solid #eee}
25	.tab{flex:1;padding:10px;text-align:center;font-size:14px;cursor:pointer;border-bottom:2px solid transparent;color:#666}
26	.tab.active{border-bottom-color:#007aff;color:#007aff;font-weight:600}
27	.form-group{margin-bottom:14px}
28	.form-group label{display:block;font-size:13px;color:#666;margin-bottom:4px}
29	.form-group input{width:100%;padding:10px 12px;border:1px solid #ddd;border-radius:6px;font-size:14px}
30	.captcha-row{display:flex;gap:8px}
31	.captcha-row input{flex:1}
32	.captcha-img{width:100px;height:40px;border-radius:6px;cursor:pointer;border:1px solid #ddd;background:#f8f9fa;display:flex;align-items:center;justify-content:center;font-size:12px;color:#999}
33	.captcha-img img{width:100%;height:100%;border-radius:6px}
34	.btn-submit{width:100%;padding:12px;border:none;border-radius:6px;background:#007aff;color:#fff;font-size:15px;cursor:pointer;margin-top:8px}
35	.btn-submit:hover{background:#0066cc}
36	.error{color:#dc3545;font-size:13px;margin-top:8px;text-align:center;display:none}
37	.back-link{display:block;text-align:center;margin-top:16px;font-size:13px;color:#007aff;text-decoration:none}
38	.back-link:hover{text-decoration:underline}
39	.tab-content{display:none}
40	.tab-content.active{display:block}
41	</style>
42	</head>
43	<body>
44	<div class="login-box">
45	  <h1>用户登录</h1>
46	  <div class="tabs">
47	    <div class="tab active" onclick="switchTab('model')" id="tab-model">模型登录</div>
48	    <div class="tab" onclick="switchTab('user')" id="tab-user">用户登录</div>
49	  </div>
50	
51	  <!-- 模型登录 -->
52	  <div class="tab-content active" id="content-model">
53	    <form id="modelLoginForm" action="UserLoginInterface" method="POST" onsubmit="return doModelLoginFormSubmit(event)">
54	      <!-- 隐藏的登录类型字段 -->
55	      <input type="hidden" name="login_type" value="model">
56	      <!-- 隐藏的验证码 ID 字段 -->
57	      <input type="hidden" name="captcha_id" id="formCaptchaId" value="">
58	
