65	        <label>API Key</label>
66	        <div style="position:relative;">
67	          <input type="password" name="api_key" id="apiKey" placeholder="请输入 API Key"
68	                 autocomplete="current-password" required
69	                 style="padding-right:36px;">
70	          <span onclick="toggleApiKeyVisibility()" title="显示/隐藏"
71	                style="position:absolute;right:10px;top:50%;transform:translateY(-50%);cursor:pointer;font-size:14px;user-select:none;">👁️</span>
72	        </div>
73	      </div>
74	      <div class="form-group">
75	        <label>验证码</label>
76	        <div class="captcha-row">
77	          <input type="text" name="captcha_code" id="modelCaptchaCode" placeholder="请输入验证码" maxlength="4"
78	                 autocomplete="off" required>
79	          <div class="captcha-img" onclick="refreshCaptcha()" title="点击刷新">
80	            <img id="captchaImg" src="" alt="验证码">
81	          </div>
82	        </div>
83	      </div>
84	      <button type="submit" class="btn-submit">登录</button>
85	    </form>
86	  </div>
87	
88	  <!-- 用户登录 -->
89	  <div class="tab-content" id="content-user">
90	    <div style="text-align:center;padding:30px 0;color:#999;">
