99	
100	<script>
101	var captchaId = '';
102	
103	// 页面加载时检查 URL 错误参数（表单提交失败重定向回来）
104	(function() {
105	  var params = new URLSearchParams(window.location.search);
106	  var err = params.get('error');
107	  if (err) {
108	    showError(decodeURIComponent(err));
109	    // 清除 URL 中的错误参数
110	    if (window.history.replaceState) {
111	      window.history.replaceState({}, document.title, window.location.pathname);
112	    }
113	  }
114	})();
115	
116	function apiUrl(path) {
117	  var pathname = window.location.pathname;
118	  var base = pathname.substring(0, pathname.lastIndexOf('/') + 1);
119	  return base + path;
120	}
121	
122	async function refreshCaptcha() {
123	  try {
124	    var resp = await fetch(apiUrl('CaptchaGenerate'), {method: 'GET'});
125	    var data = await resp.json();
126	    if (data.success) {
127	      captchaId = data.captcha_id;
128	      var imgUrl = data.image_url;
129	      document.getElementById('captchaImg').src = imgUrl;
130	      document.getElementById('captchaImg2').src = imgUrl;
131	    }
132	  } catch (e) {
133	    console.error('刷新验证码失败:', e);
134	  }
135	}
136	
137	function switchTab(type) {
138	  document.querySelectorAll('.tab').forEach(function(t) { t.classList.remove('active'); });
139	  document.querySelectorAll('.tab-content').forEach(function(c) { c.classList.remove('active'); });
140	  document.getElementById('tab-' + type).classList.add('active');
141	  document.getElementById('content-' + type).classList.add('active');
142	  document.getElementById('errorMsg').style.display = 'none';
143	}
144	
145	function showError(msg) {
146	  var el = document.getElementById('errorMsg');
147	  el.textContent = msg;
148	  el.style.display = 'block';
149	}
150	
151	// 显示/隐藏 API Key（仅前端，不影响安全）
152	function toggleApiKeyVisibility() {
153	  var input = document.getElementById('apiKey');
154	  input.type = input.type === 'password' ? 'text' : 'password';
155	}
156	
157	// 表单提交处理（传统 form 提交，支持 Chrome 密码管理器）
158	function doModelLoginFormSubmit(e) {
159	  // 同步验证码 ID 到隐藏字段
160	  document.getElementById('formCaptchaId').value = captchaId;
161	  return true; // 允许表单正常提交
162	}
163	
164	// 页面加载时获取验证码
165	document.addEventListener('DOMContentLoaded', refreshCaptcha);
166	</script>
167	</body>
168	</html>`
