12		"github.com/dchest/captcha"
13		"github.com/golang-jwt/jwt/v5"
14	)
15	
16	// ========== 常量定义 ==========
17	
18	const (
19		userTokenExpireDuration = time.Hour * 24 * 1
20		userLoginCookieName     = "lsm_user_token"
21		jwtUserSecret           = "lsm-user-jwt-secret-key-32bytes!"
22		maxLoginFailures        = 3
23		loginLockDuration       = 10 * time.Minute
24		loginFailureWindow      = time.Minute
25	)
26	
27	// ========== JWT Claims ==========
28	
29	// UserTokenClaims 用户登录 Token 声明
30	type UserTokenClaims struct {
31		UserID    uint64 `json:"user_id"`
32		UserName  string `json:"user_name"`
33		ModelName string `json:"model_name,omitempty"` // 模型登录时填充
34		LoginType string `json:"login_type"`           // "model" 或 "user"
35		jwt.RegisteredClaims
36	}
37	
38	// Valid 自定义校验
39	func (u *UserTokenClaims) Valid() error {
40		now := time.Now()
41		if u.ExpiresAt != nil && u.ExpiresAt.Time.Before(now) {
42			return fmt.Errorf("token 已过期")
43		}
44		if u.UserID == 0 {
45			return fmt.Errorf("用户 ID 无效")
46		}
47		if u.UserName == "" {
48			return fmt.Errorf("用户名不能为空")
49		}
50		return nil
51	}
52	
53	// ========== 请求/响应类型 ==========
54	
55	type userLoginReq struct {
56		LoginType   string `json:"login_type"`   // "model" 或 "user"
57		ModelName   string `json:"model_name"`   // 模型登录用
58		APIKey      string `json:"api_key"`      // 模型登录用
59		UserName    string `json:"user_name"`    // 用户登录用
60		Password    string `json:"password"`     // 用户登录用
61		Phone       string `json:"phone"`        // 用户登录用
62		CaptchaID   string `json:"captcha_id"`   // 验证码 ID
63		CaptchaCode string `json:"captcha_code"` // 验证码输入
64	}
65	
66	type userLoginResp struct {
67		Success bool        `json:"success"`
68		Message string      `json:"message"`
69		Data    interface{} `json:"data,omitempty"`
70	}
71	
72	// ========== 暴力破解防护 ==========
73	
74	type loginAttempt struct {
75		failedCount    int
76		lastFailedTime time.Time
77		lockedUntil    time.Time
78	}
79	
80	var (
81		loginAttempts   = make(map[string]*loginAttempt)
82		loginAttemptsMu sync.Mutex
83	)
84	
85	// getClientIP 获取客户端 IP
86	func getClientIP(r *http.Request) string {
87		ip := r.Header.Get("X-Forwarded-For")
88		if ip == "" {
89			ip = r.Header.Get("X-Real-IP")
90		}
91		if ip == "" {
92			ip = strings.Split(r.RemoteAddr, ":")[0]
93		}
94		return strings.TrimSpace(strings.Split(ip, ",")[0])
95	}
96	
97	// checkLoginAttempt 检查是否被锁定
98	func checkLoginAttempt(ip string) error {
99		loginAttemptsMu.Lock()
100		defer loginAttemptsMu.Unlock()
101	
102		attempt, exists := loginAttempts[ip]
103		if !exists {
104			return nil
105		}
106	
107		now := time.Now()
108		// 如果已过锁定时间，重置
109		if attempt.lockedUntil.After(now) {
110			return fmt.Errorf("登录过于频繁，请 %d 分钟后重试", int(attempt.lockedUntil.Sub(now).Minutes())+1)
111		}
112		// 如果超过 1 分钟窗口，重置失败次数
113		if now.Sub(attempt.lastFailedTime) > loginFailureWindow {
114			attempt.failedCount = 0
115		}
116	
117		return nil
118	}
119	
120	// recordLoginFailure 记录登录失败
121	func recordLoginFailure(ip string) {
122		loginAttemptsMu.Lock()
123		defer loginAttemptsMu.Unlock()
124	
125		attempt, exists := loginAttempts[ip]
126		if !exists {
127			attempt = &loginAttempt{}
128			loginAttempts[ip] = attempt
129		}
130	
131		now := time.Now()
132		// 超过窗口期重置
133		if now.Sub(attempt.lastFailedTime) > loginFailureWindow {
134			attempt.failedCount = 0
135		}
136	
137		attempt.failedCount++
138		attempt.lastFailedTime = now
139	
140		if attempt.failedCount >= maxLoginFailures {
141			attempt.lockedUntil = now.Add(loginLockDuration)
142		}
143	}
144	
145	// clearLoginAttempt 清除登录失败记录（成功时调用）
146	func clearLoginAttempt(ip string) {
147		loginAttemptsMu.Lock()
148		defer loginAttemptsMu.Unlock()
149		delete(loginAttempts, ip)
150	}
151	
152	// ========== 验证码接口 ==========
153	
154	// captchaGenerateHandle 生成验证码
155	func captchaGenerateHandle(w http.ResponseWriter, r *http.Request) {
156		w.Header().Set("Content-Type", "application/json")
157	
158		captchaID := captcha.NewLen(4)
159		var buf strings.Builder
160		err := captcha.WriteImage(&buf, captchaID, 120, 40)
161		if err != nil {
162			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "生成验证码失败"})
163			return
164		}
165	
166		imageBase64 := base64.StdEncoding.EncodeToString([]byte(buf.String()))
167		json.NewEncoder(w).Encode(map[string]interface{}{
168			"success":    true,
169			"captcha_id": captchaID,
170			"image_url":  "data:image/png;base64," + imageBase64,
171		})
172	}
173	
174	// ========== 登录接口 ==========
175	
176	// userLoginInterfaceHandle 用户登录 API
177	func userLoginInterfaceHandle(w http.ResponseWriter, r *http.Request) {
178		w.Header().Set("Content-Type", "application/json")
179	
180		if r.Method != http.MethodPost {
181			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "仅支持 POST 请求"})
182			return
183		}
184	
185		var req userLoginReq
186		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
187			if err.Error() == "http: request body too large" {
188				w.WriteHeader(http.StatusRequestEntityTooLarge)
189				json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "请求体超过大小限制"})
190				return
191			}
192			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "请求解析失败: " + err.Error()})
193			return
194		}
195	
196		clientIP := getClientIP(r)
197	
198		// 检查是否被锁定
199		if err := checkLoginAttempt(clientIP); err != nil {
200			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: err.Error()})
201			return
202		}
203	
204		// 校验验证码
205		if req.CaptchaID == "" || req.CaptchaCode == "" {
206			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "请输入验证码"})
207			return
208		}
209		if !captcha.VerifyString(req.CaptchaID, req.CaptchaCode) {
210			recordLoginFailure(clientIP)
211			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "验证码错误或已过期"})
212			return
213		}
214	
215		// 根据登录类型处理
216		var user *TAgentHttpUserInfo
217		var err error
218	
219		switch req.LoginType {
220		case "model":
221			user, err = doModelLogin(req)
222		case "user":
223			user, err = doUserLogin(req)
224		default:
225			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "未知的登录类型"})
226			return
227		}
228	
229		if err != nil {
230			recordLoginFailure(clientIP)
231			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: err.Error()})
232			return
233		}
234	
235		// 登录成功，生成 Token
236		tokenStr, err := generateUserToken(user, req.LoginType, req.ModelName)
237		if err != nil {
238			json.NewEncoder(w).Encode(userLoginResp{Success: false, Message: "生成登录凭证失败: " + err.Error()})
239			return
240		}
241	
242		// 设置 Cookie
243		cookie := &http.Cookie{
244			Name:     userLoginCookieName,
245			Value:    tokenStr,
246			Path:     "/",
247			HttpOnly: true,
248			Secure:   false,
249			SameSite: http.SameSiteLaxMode,
250			MaxAge:   int(userTokenExpireDuration.Seconds()),
251		}
252		http.SetCookie(w, cookie)
253	
254		clearLoginAttempt(clientIP)
255	
256		// 记录登录日志
257		loginTypeStr := "用户登录"
258		if req.LoginType == "model" {
259			loginTypeStr = fmt.Sprintf("模型登录(%s)", req.ModelName)
260		}
261		LogUserAction("LOGIN", user.UserName, fmt.Sprintf("登录方式=%s IP=%s", loginTypeStr, clientIP))
262	
263		json.NewEncoder(w).Encode(userLoginResp{
264			Success: true,
265			Message: "登录成功",
266			Data: map[string]interface{}{
267				"user_id":    user.ID,
268				"user_name":  user.UserName,
269				"login_type": req.LoginType,
270			},
271		})
272	}
273	
274	// doModelLogin 模型登录验证
275	func doModelLogin(req userLoginReq) (*TAgentHttpUserInfo, error) {
276		if req.ModelName == "" || req.APIKey == "" {
277			return nil, fmt.Errorf("模型名称和 API Key 不能为空")
278		}
279	
280		// 通过 API Key 查找模型（复用缓存+数据库查询）
281		model, err := GetUserModelByAPIKey(req.APIKey)
282		if err != nil {
283			return nil, fmt.Errorf("API Key 无效")
284		}
285	
286		// 校验模型名称是否匹配
287		if model.ModelName != strings.TrimSpace(req.ModelName) {
288			return nil, fmt.Errorf("模型名称不匹配")
289		}
290	
291		// 通过 UserID 获取用户信息（优先缓存）
292		user, ok := GetCachedUserByID(model.UserID)
293		if !ok {
294			// 缓存未命中，从数据库查询
295			user, err = GetUserByID(model.UserID)
296			if err != nil {
297				return nil, fmt.Errorf("用户不存在")
298			}
299		}
300	
301		return user, nil
302	}
303	
304	// doUserLogin 用户登录验证
305	func doUserLogin(req userLoginReq) (*TAgentHttpUserInfo, error) {
306		if req.UserName == "" || req.Password == "" || req.Phone == "" {
307			return nil, fmt.Errorf("用户名、密码和手机号不能为空")
308		}
309	
310		// 通过用户名获取用户（优先缓存）
311		user, ok := GetCachedUserByName(strings.TrimSpace(req.UserName))
312		if !ok {
313			// 缓存未命中，从数据库查询
314			var err error
315			user, err = GetUserByName(strings.TrimSpace(req.UserName))
316			if err != nil {
317				return nil, fmt.Errorf("用户名或密码错误")
318			}
319		}
320	
321		// 校验密码
322		if user.Password != strings.TrimSpace(req.Password) {
323			return nil, fmt.Errorf("用户名或密码错误")
324		}
325	
326		// 校验手机号
327		if user.Phone != strings.TrimSpace(req.Phone) {
328			return nil, fmt.Errorf("手机号不匹配")
329		}
330	
331		return user, nil
332	}
333	
334	// ========== JWT Token 管理 ==========
335	
336	// generateUserToken 生成用户 JWT Token
337	func generateUserToken(user *TAgentHttpUserInfo, loginType, modelName string) (string, error) {
338		now := time.Now()
339		claims := &UserTokenClaims{
340			UserID:    user.ID,
341			UserName:  user.UserName,
342			ModelName: modelName,
343			LoginType: loginType,
344			RegisteredClaims: jwt.RegisteredClaims{
345				ExpiresAt: jwt.NewNumericDate(now.Add(userTokenExpireDuration)),
346				IssuedAt:  jwt.NewNumericDate(now),
347				NotBefore: jwt.NewNumericDate(now),
348			},
349		}
350	
351		token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
352		return token.SignedString([]byte(jwtUserSecret))
353	}
354	
355	// getUserToken 从请求中解析用户 Token
356	func getUserToken(r *http.Request) *UserTokenClaims {
357		claims := &UserTokenClaims{}
358		tokenStr := ""
359	
360		// 1. 优先从 Cookie 获取
361		cookie, err := r.Cookie(userLoginCookieName)
362		if err == nil {
363			tokenStr = cookie.Value
364		}
365	
366		// 2.  fallback 到 Authorization header
367		if tokenStr == "" {
368			authHeader := r.Header.Get("Authorization")
369			if authHeader != "" {
370				parts := strings.SplitN(authHeader, " ", 2)
371				if len(parts) == 2 && strings.EqualFold(parts[0], "Bearer") {
372					tokenStr = parts[1]
373				}
374			}
375		}
376	
377		// 3. 解析并验证 JWT
378		if tokenStr != "" {
379			token, err := jwt.ParseWithClaims(tokenStr, claims, func(token *jwt.Token) (interface{}, error) {
380				if _, ok := token.Method.(*jwt.SigningMethodHMAC); !ok {
381					return nil, fmt.Errorf("不支持的签名算法: %v", token.Header["alg"])
382				}
383				return []byte(jwtUserSecret), nil
384			})
385			if err != nil || !token.Valid {
386				return &UserTokenClaims{}
387			}
388		}
389	
390		return claims
391	}
392	
393	// userAuthMiddleware 用户认证中间件
394	func userAuthMiddleware(next http.Handler) http.Handler {
395		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
396			// 公开路由放行
397			publicPaths := map[string]bool{
398				"/UserLogin":          true,
399				"/CaptchaGenerate":    true,
400				"/UserLoginInterface": true,
401			}
402			if len(r.URL.Path) > 8 && r.URL.Path[:8] == "/static/" {
403				next.ServeHTTP(w, r)
404				return
405			}
406			if publicPaths[r.URL.Path] {
407				next.ServeHTTP(w, r)
408				return
409			}
410	
411			// 验证 Token
412			claims := getUserToken(r)
413			if claims.UserID == 0 {
414				http.Redirect(w, r, "/UserLogin", http.StatusFound)
415				return
416			}
417	
418			next.ServeHTTP(w, r)
419		})
420	}
