  var userName = document.getElementById('userName').value.trim();
  var password = document.getElementById('userPassword').value.trim();
  var phone = document.getElementById('userPhone').value.trim();
  var captchaCode = document.getElementById('userCaptchaCode').value.trim();
  if (!userName || !password || !phone || !captchaCode) {
    showError('请填写完整信息'); return;
  }
  await doLogin({login_type: 'user', user_name: userName, password: password, phone: phone, captcha_id: captchaId, captcha_code: captchaCode});
}

async function doLogin(body) {
  try {
    var resp = await fetch(apiUrl('UserLoginInterface'), {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(body)
    });
    var data = await resp.json();
    if (data.success) {
      window.location.href = './';
    } else {
      showError(data.message || '登录失败');
      refreshCaptcha();
    }
  } catch (e) {
    showError('请求失败: ' + e.message);
  }
}

